/* HTMX is vendored during the build. This fallback provides the MVP interactions when offline. */
document.addEventListener("submit",async e=>{const f=e.target;if(!f.matches("[hx-post]"))return;e.preventDefault();const target=document.querySelector(f.getAttribute("hx-target"));const indicator=document.querySelector(f.getAttribute("hx-indicator")||"x-none");const body=new FormData(f);f.dispatchEvent(new CustomEvent("htmx:beforeRequest",{bubbles:true,detail:{elt:f,target}}));f.classList.add("htmx-request");indicator?.classList.add("htmx-request");try{const res=await fetch(f.getAttribute("hx-post"),{method:"POST",body,headers:{"HX-Request":"true"}});const html=await res.text();if(target){target.outerHTML=html;const swapped=document.querySelector(f.getAttribute("hx-target"));f.dispatchEvent(new CustomEvent("htmx:afterSwap",{bubbles:true,detail:{elt:f,target:swapped}}))}if(res.ok)f.reset();else if(target)target.insertAdjacentHTML("beforebegin",html);f.dispatchEvent(new CustomEvent("htmx:afterRequest",{bubbles:true,detail:{elt:f,target,successful:res.ok}}))}finally{f.classList.remove("htmx-request");indicator?.classList.remove("htmx-request")}});
document.addEventListener("click",e=>{const b=e.target.closest("[hx-confirm]");if(b&&!confirm(b.getAttribute("hx-confirm")))e.preventDefault()});
